# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PAST TIME EXPRESSIONS &amp; CONJUNCTIONS IN BIOGRAPHIES</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Past Time Expressions (Zaman Zarfları)</text>\n  <text x="44" y="100" font-size="11.5" fill="#334155">• in + year / century: in 1881, in the 20th century</text>\n  <text x="44" y="124" font-size="11.5" fill="#334155">• on + full date / day: on May 19, 1919</text>\n  <text x="44" y="148" font-size="11.5" fill="#334155">• ... ago (önce): ten years ago, two centuries ago</text>\n  <text x="44" y="172" font-size="11.5" fill="#334155">• last ... (geçen): last week, last month, last year</text>\n  <text x="44" y="196" font-size="11.5" fill="#334155">• yesterday (dün): yesterday morning</text>\n  <text x="183" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">He graduated from university five years ago.</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Conjunctions (Zaman ve Neden Bağlaçları)</text>\n  <text x="378" y="100" font-size="11.5" fill="#334155">• when (-dığında): She was 24 when she moved to Paris.</text>\n  <text x="378" y="124" font-size="11.5" fill="#334155">• until (-e kadar): He lived in İzmir until 2015.</text>\n  <text x="378" y="148" font-size="11.5" fill="#334155">• before / after (önce / sonra): After he graduated, ...</text>\n  <text x="378" y="172" font-size="11.5" fill="#334155">• because (çünkü - sebep): ... because he worked hard.</text>\n  <text x="378" y="196" font-size="11.5" fill="#334155">• so (bu yüzden - sonuç): ... so he won the Nobel Prize.</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">to + V1 (amaç): She went to Rome to study art.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HOW TO WRITE A SHORT BIOGRAPHY REPORT (E7.3.W1)</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="130" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">1. Early Life &amp; Education</text>\n  <text x="40" y="100" font-size="11" fill="#334155">• Birth Date &amp; Place:</text>\n  <text x="46" y="116" font-size="10.5" fill="#475569">"He was born in Mardin in 1946."</text>\n  <text x="40" y="140" font-size="11" fill="#334155">• Childhood &amp; Growing up:</text>\n  <text x="46" y="156" font-size="10.5" fill="#475569">"He grew up in a large family."</text>\n  <text x="40" y="180" font-size="11" fill="#334155">• Graduation:</text>\n  <text x="46" y="196" font-size="10.5" fill="#475569">"He graduated from İstanbul Univ."</text>\n  <text x="130" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">was/were born · grew up · graduated</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">2. Career &amp; Family Life</text>\n  <text x="260" y="100" font-size="11" fill="#334155">• Moving &amp; Profession:</text>\n  <text x="266" y="116" font-size="10.5" fill="#475569">"He moved to the USA to do research."</text>\n  <text x="260" y="140" font-size="11" fill="#334155">• Marriage &amp; Children:</text>\n  <text x="266" y="156" font-size="10.5" fill="#475569">"He got married to Gwen Sancar."</text>\n  <text x="260" y="180" font-size="11" fill="#334155">• Hard Work:</text>\n  <text x="266" y="196" font-size="10.5" fill="#475569">"He worked on DNA repair for years."</text>\n  <text x="350" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">moved to · got married · raised kids</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="570" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">3. Achievements &amp; Later Life</text>\n  <text x="480" y="100" font-size="11" fill="#334155">• Inventions / Works:</text>\n  <text x="486" y="116" font-size="10.5" fill="#475569">"He mapped how cells repair DNA."</text>\n  <text x="480" y="140" font-size="11" fill="#334155">• Awards &amp; Prizes:</text>\n  <text x="486" y="156" font-size="10.5" fill="#475569">"He won the Nobel Prize in 2015."</text>\n  <text x="480" y="180" font-size="11" fill="#334155">• Death (for past figures):</text>\n  <text x="486" y="196" font-size="10.5" fill="#475569">"She died in 1934 at the age of 66."</text>\n  <text x="570" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">won an award · discovered · died</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">UNIT 3 REVISION: QUESTION WORDS &amp; FAMOUS BIOGRAPHIES</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Wh- Questions in Simple Past Tense</text>\n  <text x="44" y="98" font-size="11.5" fill="#334155">• WHEN / WHAT TIME: Zaman sorar</text>\n  <text x="52" y="114" font-size="10.5" fill="#475569">When was she born? → In 1867.</text>\n  <text x="44" y="136" font-size="11.5" fill="#334155">• WHERE: Yer / Mekân sorar</text>\n  <text x="52" y="152" font-size="10.5" fill="#475569">Where did he grow up? → In London.</text>\n  <text x="44" y="174" font-size="11.5" fill="#334155">• WHY: Sebep / Amaç sorar</text>\n  <text x="52" y="190" font-size="10.5" fill="#475569">Why did he move? → To study physics / Because...</text>\n  <text x="183" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">WHO (Kim) · WHAT (Ne) · HOW MANY (Kaç tane)</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Historical Figures &amp; Milestones Summary</text>\n  <text x="378" y="98" font-size="11" fill="#334155">• Mustafa Kemal Atatürk (1881 - Nov 10, 1938):</text>\n  <text x="386" y="114" font-size="10.5" fill="#475569">Founder ve first President of the Republic of Türkiye.</text>\n  <text x="378" y="136" font-size="11" fill="#334155">• Marie Curie (1867 - 1934):</text>\n  <text x="386" y="152" font-size="10.5" fill="#475569">Discovered radium &amp; polonium; won two Nobel Prizes.</text>\n  <text x="378" y="174" font-size="11" fill="#334155">• Nikola Tesla / Albert Einstein / İdil Biret:</text>\n  <text x="386" y="190" font-size="10.5" fill="#475569">Brilliant scientists, inventors and talented artists.</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">brilliant · extraordinary · hardworking · alone</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
